{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Maestro Project Blueprint",
  "type": "object",
  "properties": {
    "projectId": { "type": "string", "format": "uuid" },
    "projectName": { "type": "string", "description": "Midnight Ride" },
    "version": { "type": "string", "description": "1.0.0" },
    "lastUpdated": { "type": "string", "format": "date-time" },
    "creativeBrief": {
      "type": "object",
      "properties": {
        "initialPrompt": { "type": "string", "description": "A Gospel track reimagined as a G-funk meets Houston trill bounce masterpiece, featuring a male quartet reminiscent of 90s R&B boy bands revived for Generation Z. Emphasize vocal techniques like melisma, vocal fry, microtonal singing, circular breathing, and ingressive phonation to convey a deep, emotional narrative of struggle and spiritual seeking, taking praise to the youth of 2025. The song should have a raw, authentic, and live studio feel with improvisational elements." },
        "primaryGenre": { "type": "string", "examples": ["Gospel (Reimagined)"] },
        "secondaryGenre": { "type": "array", "items": { "type": "string" }, "examples": ["G-funk", "Houston Trill Bounce", "90s R&B", "Contemporary R&B"] },
        "mood": { "type": "array", "items": { "type": "string" }, "examples": [["ache", "denial", "struggle", "introspective", "pleading", "resilient", "soulful"]] },
        "key": { "type": "string", "examples": ["G minor"] },
        "bpm": { "type": "integer", "examples": [78] }
      },
      "required": ["initialPrompt", "primaryGenre"]
    },
    "songStructure": {
      "type": "array",
      "items": { "$ref": "#/definitions/songSection" }
    },
    "productionNotes": {
      "type": "object",
      "description": "Global production directives",
      "properties": {
        "overallMix": {
          "type": "array",
          "items": { "type": "string" },
          "examples": [
            ["emphasize deep, syrupy basslines characteristic of G-funk and Southern Trap",
             "crisp, driving Houston trill bounce drums with prominent 808s",
             "lush, layered vocal harmonies with a contemporary R&B sheen",
             "subtle lo-fi elements to hint at 90s R&B authenticity",
             "mix should feel live and dynamic, as if captured in a studio session"
            ]
          ]
        },
        "masteringDirectives": {
          "type": "array",
          "items": { "type": "string" },
          "examples": [
            ["optimize for streaming platforms, ensuring deep bass presence without muddiness",
             "maintain vocal clarity and presence amidst instrumental layers",
             "target -14 LUFS with controlled dynamic range to allow vocal nuances to shine"
            ]
          ]
        },
        "sunoSpecific": {
          "type": "object",
          "properties": {
            "usePersonaId": { "type": "string" },
            "isCoverOf": { "type": "string", "description": "Project ID of the original track" }
          }
        }
      }
    },
    "feedbackLog": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "version": { "type": "string" },
          "timestamp": { "type": "string", "format": "date-time" },
          "source": { "enum": ["automated_critique", "user_feedback"] },
          "comment": { "type": "string" },
          "audioMetrics": {
            "type": "object",
            "properties": {
              "lufs": { "type": "number" },
              "dynamicRange": { "type": "number" }
            }
          }
        }
      }
    }
  },
  "required": ["projectId", "projectName", "version", "creativeBrief", "songStructure"],
  "definitions": {
    "songSection": {
      "type": "object",
      "properties": {
        "sectionName": { "enum": ["[Intro]", "[Verse]", "[Pre-Chorus]", "[Chorus]", "[Bridge]", "[Guitar Solo]", "[Instrumental]", "[Outro]", "[Post-Chorus]"] },
        "durationBars": { "type": "integer" },
        "lyrics": { "type": "string" },
        "instrumentation": {
          "type": "array",
          "items": { "type": "string" },
          "examples": [["808 kick", "Rhodes piano"], ["distorted electric guitar"]]
        },
        "performanceNotes": {
          "type": "array",
          "items": { "type": "string" },
          "description": "How the section should be performed.",
          "examples": [["vocal delivery: delicate, intimate performance"], ["drums: driving and energetic"]]
        },
        "productionCues": {
          "type": "array",
          "items": { "type": "string" },
          "description": "Mixing/effects notes for this section.",
          "examples": [["apply heavy reverb to snare"], ["pan guitars wide"]]
        }
      },
      "required": ["sectionName", "lyrics"]
    }
  },
  "example": {
    "projectId": "auto-generated-uuid",
    "projectName": "Midnight Ride",
    "version": "1.0.0",
    "lastUpdated": "20

